fn encode_cyclic(mut s: Vec<i8>) -> Vec<i8> {
    let len = s.len();
    // Compute the largest multiple of 3 ≤ len
    let l = len - (len % 3);

    // For each full block of 3, rotate left: [a, b, c] -> [b, c, a]
    for i in (0..l).step_by(3) {
        let tmp = s[i];
        s[i] = s[i + 1];
        s[i + 1] = s[i + 2];
        s[i + 2] = tmp;
    }

    // Any leftover elements at the end (len % 3 of them) remain unchanged.
    s
}

